namespace sv_1f832ac82627440793b5a07c28a1bd12.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service that holds the currently selected warehouse per circuit (per user).
/// Components subscribe to OnChange to react when the warehouse selection changes.
/// </summary>
public class WarehouseState
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "wh-1", Name = "Warehouse A — Downtown" },
        new() { Id = "wh-2", Name = "Warehouse B — Airport" },
        new() { Id = "wh-3", Name = "Warehouse C — Harbor" },
    ];

    public IReadOnlyList<WarehouseInfo> AvailableWarehouses => _allWarehouses;

    public WarehouseInfo CurrentWarehouse { get; private set; } = _allWarehouses[0];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = _allWarehouses.Find(w => w.Id == warehouseId);
        if (warehouse is not null && warehouse.Id != CurrentWarehouse.Id)
        {
            CurrentWarehouse = warehouse;
            OnChange?.Invoke();
        }
    }
}

namespace sv_1f832ac82627440793b5a07c28a1bd12.Services;

/// <summary>
/// Simulates a database query for low-stock item counts.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database query
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }
}

namespace sv_1f832ac82627440793b5a07c28a1bd12.Services;

/// <summary>
/// Scoped service that manages polling for low-stock alerts.
/// Polling is ref-counted: starts when first subscriber requests it, stops when last unsubscribes.
/// All subscribers are notified when new data arrives.
/// </summary>
public class InventoryAlertState : IDisposable
{
    private readonly InventoryAlertService _alertService;
    private readonly WarehouseState _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _pollingSubscribers;

    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    public InventoryAlertState(InventoryAlertService alertService, WarehouseState warehouseState)
    {
        _alertService = alertService;
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    private async void OnWarehouseChanged()
    {
        // Refresh immediately when warehouse changes and polling is active
        if (_pollingSubscribers > 0)
        {
            await RefreshAsync();
        }
    }

    public async Task StartPollingAsync()
    {
        _pollingSubscribers++;
        if (_pollingSubscribers == 1)
        {
            await RefreshAsync();
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void StopPolling()
    {
        _pollingSubscribers = Math.Max(0, _pollingSubscribers - 1);
        if (_pollingSubscribers == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(cancellationToken))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped
        }
    }

    private async Task RefreshAsync()
    {
        LowStockCount = await _alertService.GetLowStockCountAsync(_warehouseState.CurrentWarehouse.Id);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

