namespace sv_1f832ac82627440793b5a07c28a1bd12.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service that holds the currently selected warehouse per circuit (per user).
/// Components subscribe to OnChange to react when the warehouse selection changes.
/// </summary>
public class WarehouseState
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "wh-1", Name = "Warehouse A — Downtown" },
        new() { Id = "wh-2", Name = "Warehouse B — Airport" },
        new() { Id = "wh-3", Name = "Warehouse C — Harbor" },
    ];

    public IReadOnlyList<WarehouseInfo> AvailableWarehouses => _allWarehouses;

    public WarehouseInfo CurrentWarehouse { get; private set; } = _allWarehouses[0];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = _allWarehouses.Find(w => w.Id == warehouseId);
        if (warehouse is not null && warehouse.Id != CurrentWarehouse.Id)
        {
            CurrentWarehouse = warehouse;
            OnChange?.Invoke();
        }
    }
}

