@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 small text-white-50">Current Warehouse</label>
    <select class="form-select form-select-sm" value="@WarehouseState.CurrentWarehouse.Id"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertState AlertState
@implements IDisposable

<span class="alert-badge">
    @if (AlertState.LowStockCount > 0)
    {
        <span class="badge bg-danger">@AlertState.LowStockCount</span>
    }
    else
    {
        <span class="badge bg-success">0</span>
    }
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertState.OnChange += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertState.OnChange -= _handler;
        }
    }
}

